import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mix, color, fract, sin, dot, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const root = new Group();
  const disposables = [];
  const timelines = [];

  const colors =
    config.intent?.visualSpec?.colors ?? {
      background: '#0b0b10',
      surface: '#14141a',
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
    };
  const bgHex = colors.gradientStops?.[0]?.hex ?? colors.background ?? '#0b0b10';
  const surfHex = colors.gradientStops?.[1]?.hex ?? colors.surface ?? '#14141a';
  const paperHex = colors.paper ?? '#e8ecf2';
  const inkHex = colors.ink ?? '#16161d';
  const accentHex = colors.accent ?? '#ff2a38';

  // ---- Stage backdrop (7 x 6 at z = -2.5), engineered vertical gradient ----
  const stageGeo = new PlaneGeometry(7, 6);
  const stageMat = new MeshBasicNodeMaterial();
  stageMat.colorNode = mix(color(bgHex), color(surfHex), uv().y);
  const stage = new Mesh(stageGeo, stageMat);
  stage.position.set(0, 0, -2.5);
  root.add(stage);
  disposables.push(stageGeo, stageMat);

  // ---- Editorial plate (7 x 5.5 at z = 0) with gradient + 1.5% monochrome grain ----
  const plateGeo = new PlaneGeometry(7, 5.5);
  const plateMat = new MeshBasicNodeMaterial();
  const grain = fract(
    sin(dot(uv().mul(float(742.0)), vec2(12.9898, 78.233))).mul(43758.5453)
  )
    .sub(0.5)
    .mul(0.03); // +/- 1.5% monochrome grain
  plateMat.colorNode = mix(color(bgHex), color(surfHex), uv().y).add(grain);
  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, 0);
  root.add(plate);
  disposables.push(plateGeo, plateMat);

  // ---- Text content (verbatim from spec) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.filter((i) => i.role === role);
  const kickerItem = byRole('kicker')[0];
  const heroItems = byRole('hero');
  const bodyItem = byRole('body')[0];
  const captionItem = byRole('caption')[0];

  const LEFT_X = -3.1;
  const TEXT_Z = 0.05;
  const blocks = []; // animated in top-to-bottom order

  // Kicker — JetBrains Mono 700, uppercase, tracking 0.12em
  if (kickerItem) {
    const kickerSize = kickerItem.typography?.fontSize ?? 18;
    const kicker = ctx.fontAtlas.createText(String(kickerItem.text), {
      fontSize: kickerSize,
      color: accentHex,
      align: 'left',
      letterSpacingPx: kickerSize * 0.12,
    });
    kicker.position.set(LEFT_X, 1.7, TEXT_Z);
    root.add(kicker);
    blocks.push({ obj: kicker, y: 1.7 });
  }

  // Hero — two stacked lines, Lora 600, tracking -0.015em, letterpress shadow behind
  const heroYs = [0.9, 0.25];
  heroItems.forEach((item, idx) => {
    const heroSize = item.typography?.fontSize ?? 124;
    const y = heroYs[idx] ?? heroYs[heroYs.length - 1] - 0.65 * (idx - 1);

    // Letterpress shadow duplicate, 0.02 units behind, ink color
    const shadow = ctx.fontAtlas.createText(String(item.text), {
      fontSize: heroSize,
      color: inkHex,
      align: 'left',
      letterSpacingPx: heroSize * -0.015,
    });
    shadow.position.set(LEFT_X + 0.02, y - 0.02, TEXT_Z - 0.02);
    root.add(shadow);

    const line = ctx.fontAtlas.createText(String(item.text), {
      fontSize: heroSize,
      color: paperHex,
      align: 'left',
      letterSpacingPx: heroSize * -0.015,
    });
    line.position.set(LEFT_X, y, TEXT_Z);
    root.add(line);

    blocks.push({ obj: line, y, shadow, shadowY: y - 0.02 });
  });

  // ---- Accent underline rule 2.2 x 0.05, emissive-graded accent, draws from left ----
  const ruleGeo = new PlaneGeometry(2.2, 0.05);
  ruleGeo.translate(1.1, 0, 0); // pivot at left edge so scaleX grows rightward
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = color(accentHex).mul(1.2);
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(LEFT_X, -0.15, TEXT_Z);
  rule.scale.x = 0.0001;
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // Body — max-width 4.5 scene units (~ pixel proportional to plate mapping)
  if (bodyItem) {
    const bodySize = bodyItem.typography?.fontSize ?? 26;
    const body = ctx.fontAtlas.createText(String(bodyItem.text), {
      fontSize: bodySize,
      color: paperHex,
      align: 'left',
      maxWidthPx: 640,
    });
    body.position.set(LEFT_X, -0.8, TEXT_Z);
    root.add(body);
    blocks.push({ obj: body, y: -0.8 });
  }

  // Caption — tracking 0.08em
  if (captionItem) {
    const capSize = captionItem.typography?.fontSize ?? 18;
    const caption = ctx.fontAtlas.createText(String(captionItem.text), {
      fontSize: capSize,
      color: paperHex,
      align: 'left',
      letterSpacingPx: capSize * 0.08,
    });
    caption.position.set(LEFT_X, -1.9, TEXT_Z);
    root.add(caption);
    blocks.push({ obj: caption, y: -1.9 });
  }

  // ---- Entrance: rise-in per block top-to-bottom, 0.7s power3.out, 80ms stagger ----
  const tl = gsap.timeline();
  timelines.push(tl);
  blocks.forEach((b, i) => {
    b.obj.position.y = b.y + 0.4;
    b.obj.visible = false;
    const at = i * 0.08;
    tl.set(b.obj, { visible: true }, at);
    tl.to(b.obj.position, { y: b.y, duration: 0.7, ease: 'power3.out' }, at);
    if (b.shadow) {
      b.shadow.position.y = b.shadowY + 0.4;
      b.shadow.visible = false;
      tl.set(b.shadow, { visible: true }, at);
      tl.to(b.shadow.position, { y: b.shadowY, duration: 0.7, ease: 'power3.out' }, at);
    }
  });
  // Rule draws scaleX 0 -> 1 after the hero lands
  const heroLandAt = 0.08 * Math.max(1, blocks.length > 1 ? 2 : 1) + 0.7;
  tl.to(rule.scale, { x: 1, duration: 0.5, ease: 'power2.out' }, heroLandAt);

  // ---- Cinematic primitives from config (none expected, but honor contract) ----
  const primHandles = [];
  for (const primitive of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[primitive.name];
    if (fn) primHandles.push(fn(root, primitive.params));
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primHandles.forEach((h) => h?.cleanup?.());
    disposables.forEach((d) => d?.dispose?.());
    root.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose?.();
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => m?.dispose?.());
      }
    });
  };

  return root;
}
